def catalogue():
    entries = []
    for entity_id, name, case_rows in PEOPLE:
        forms = []
        for row in case_rows:
            first, patronymic, surname = row.split()
            forms.extend([row, f"{first} {surname}", surname])
        entries.append(dict(id=entity_id, name=name, type="PERSON", forms=forms,
                            base_source={"kind": "corpus", "id": entity_id}))
    for kind, rows in (("ORG", ORGANIZATIONS), ("LOC", LOCATIONS)):
        for entity_id, name, doc_id, forms in rows:
            entries.append(dict(id=entity_id, name=name, type=kind, forms=forms,
                                base_source={"kind": "corpus", "id": doc_id}))
    for entity_id, name, kind, query_id, forms in DEV_ONLY:
        entries.append(dict(id=entity_id, name=name, type=kind, forms=forms,
                            base_source={"kind": "dev", "id": query_id}))
    return entries
